(function () {
  function serialize(form) {
    return new URLSearchParams(new FormData(form)).toString();
  }
  async function submit(event) {
    var trigger = event.submitter || document.activeElement;
    var form = event.target;
    var url = trigger && trigger.getAttribute("hx-post") || form.getAttribute("hx-post");
    if (!url) return;
    event.preventDefault();
    var targetSelector = trigger && trigger.getAttribute("hx-target") || form.getAttribute("hx-target");
    var target = targetSelector ? document.querySelector(targetSelector) : null;
    var response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8" },
      body: serialize(form)
    });
    var text = await response.text();
    if (target) target.innerHTML = text;
    if (!target && response.redirected) window.location.href = response.url;
  }
  document.addEventListener("submit", function (event) {
    if (event.target && event.target.matches("form")) submit(event);
  });
})();
